import * as THREE from 'three/webgpu';
import { uv, texture, mix, color, vec4, fract, sin, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const colors = config.visualSpec?.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const group = new THREE.Group();
  group.userData.handlers = {};

  const rect = config.atlasRegion || { x: 0, y: 0, w: 512, h: 320 };
  const aspect = rect.w / rect.h;
  const planeW = 1.6;
  const planeH = planeW / aspect;

  const geometry = new THREE.PlaneGeometry(planeW, planeH);

  const tex = ctx.textureLoader.load('/prism-mock/home/nodes/orb-decor.png');
  if (tex) tex.colorSpace = THREE.SRGBColorSpace;

  const uvNode = uv();
  const texColor = tex ? texture(tex, uvNode) : vec4(0.04, 0.04, 0.06, 1.0);

  // Engineered gradient: surface (bottom) -> ink (top)
  const grad = mix(color(colors.surface), color(colors.ink), uvNode.y);

  // Subtle grain
  const grain = fract(sin(uvNode.x.mul(12.9898).add(uvNode.y.mul(78.233))).mul(43758.5453));
  const grainOffset = grain.sub(0.5).mul(0.035);

  // Composite: texture dominant, gradient undertone, grain
  const baseColor = texColor.rgb.mul(0.9).add(grad.mul(0.1));
  const finalColor = baseColor.add(grainOffset);

  const opacityUniform = uniform(0);

  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = finalColor;
  material.opacityNode = opacityUniform.mul(texColor.a);
  material.transparent = true;
  material.side = THREE.DoubleSide;

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  const pos = config.scenePosition;
  const rot = config.sceneRotation;
  const scl = config.sceneScale;

  group.position.set(pos.x, pos.y, pos.z);
  group.rotation.set(rot.x, rot.y, rot.z);
  group.scale.set(scl.x, scl.y, scl.z);

  // One-shot fade-up entrance (non-interactive)
  group.position.y = pos.y + 0.2;
  const timelines = [];
  const tl = gsap.timeline();
  tl.to(opacityUniform, { value: 1, duration: 0.5, ease: 'power2.out' }, 0)
    .to(group.position, { y: pos.y, duration: 0.7, ease: 'power3.out' }, 0);
  timelines.push(tl);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    timelines.forEach(t => t.kill());
    geometry.dispose();
    material.dispose();
  };

  return group;
}
